from ortools.sat.python import cp_model

def solve_latin_square(grid):
    model = cp_model.CpModel()
    n = 11

    # Variables
    x = {}
    for i in range(n):
        for j in range(n):
            x[i, j] = model.NewIntVar(0, n - 1, f'x[{i},{j}]')

    # Constraints
    # Pre-filled
    for i in range(n):
        for j in range(n):
            if grid[i * n + j] != -1:
                model.Add(x[i, j] == grid[i * n + j])

    # Rows
    for i in range(n):
        model.AddAllDifferent([x[i, j] for j in range(n)])

    # Columns
    for j in range(n):
        model.AddAllDifferent([x[i, j] for i in range(n)])

    # Solve
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        result = []
        for i in range(n):
            for j in range(n):
                result.append(solver.Value(x[i, j]))
        return result
    else:
        return None

