# Since I cannot use ortools, I will use a simple backtracking solver.
# The grid is 11x11, which is small enough for a backtracking solver.

def is_valid(grid, row, col, num):
    # Check row
    for j in range(11):
        if grid[row * 11 + j] == num:
            return False
    # Check column
    for i in range(11):
        if grid[i * 11 + col] == num:
            return False
    return True

def solve(grid):
    for i in range(121):
        if grid[i] == -1:
            row = i // 11
            col = i % 11
            for num in range(11):
                if is_valid(grid, row, col, num):
                    grid[i] = num
                    if solve(grid):
                        return True
                    grid[i] = -1
            return False
    return True

