def check_latin_square(grid):
    n = 11
    # Check rows
    for i in range(n):
        row = [grid[i * n + j] for j in range(n)]
        if sorted(row) != list(range(n)):
            return False, f"Row {i} invalid: {row}"
    # Check columns
    for j in range(n):
        col = [grid[i * n + j] for i in range(n)]
        if sorted(col) != list(range(n)):
            return False, f"Col {j} invalid: {col}"
    return True, "Valid"

